  it('lets you continue playing once an incomplete replay runs out of moves', async () => {
    const warn = sinon.stub(console, 'warn')

    const game = renderGame()

    // A one-move replay doesn't end the game
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns('D')
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()

    // The replay plays its single move and control
    // returns to the player
    await advanceReplaySteps(2)

    const replayingText = screen.queryByText('replaying...')
    const downCount = screen.queryAllByTestId('down').length

    // and the player can actually play
    await user.keyboard('{Down}')
    const downCountAfterMove = screen.queryAllByTestId('down').length
    const warnCount = warn.getCalls().length

    game.unmount()
    warn.restore()

    assert.equal(replayingText, null)
    assert.equal(downCount, 1)
    assert.equal(downCountAfterMove, 1)
    assert.equal(warnCount, 0)
  })

  it('keeps the game over screen when a complete replay ends the game on its last move', async () => {
    const warn = sinon.stub(console, 'warn')

    const game = renderGame()

    await user.click(screen.getByTestId('select-ai'))
    await user.click(screen.queryAllByTestId('enemy')[2])

    // Lovetris always sends I pieces, and 187 downs ends the
    // game on the last move (see the full-game test above)
    const moves = 'D'.repeat(187)
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns(moves)
    await user.click(screen.getByTestId('replay-button'))
    prompt.restore()

    await advanceReplaySteps(190)

    const replayOut = screen.getByTestId('replay-out').textContent
    const downCount = screen.queryAllByTestId('down').length
    const warnCount = warn.getCalls().length

    game.unmount()
    warn.restore()

    assert.equal(replayOut, hatetrisReplayCodec.encode(moves.split('')))
    assert.equal(downCount, 0)
    assert.equal(warnCount, 0)
  })

