          // shift right as many times as necessary
          const rows = allRows.slice(yMin, yMax).map(row => row >> xMin)

          return {
            xMin,
            yMin,
            xDim: xMax - xMin,
            yDim: yMax - yMin,
            rows
          }
        })
    ])
)

